// 각 callback 라우트에 미들웨어 추가:
router.get('/google/callback',
  validate(oauthCallbackSchema, 'query'),  // code/state 검증
  async (req, res) => { ... }
);
```

**수정 파일:** `/tmp/freelang-light/src/server.ts`

