  -d '{"code": "a3f9..."}'
# 응답: 401 Invalid or expired auth code

# 4. Refresh 동작:
curl -X POST http://localhost:3001/auth/refresh \
  --cookie "refreshToken=eyJ..."
# 응답: {"accessToken": "eyJ...새토큰..."}
```

