```typescript
// 추가할 테스트 케이스 (의사 코드):
describe('Token Pair', () => {
  it('access token expires in 15 minutes', () => {
    const { accessToken } = oauthHandler.generateTokenPair(mockUser);
    const payload = jwt.decode(accessToken) as any;
    const expiresIn = payload.exp - payload.iat;
    expect(expiresIn).toBe(900);  // 15분 = 900초
  });

  it('refresh token expires in 30 days', () => {
    const { refreshToken } = oauthHandler.generateTokenPair(mockUser);
    const payload = jwt.decode(refreshToken) as any;
    const expiresIn = payload.exp - payload.iat;
    expect(expiresIn).toBe(2592000);  // 30일
  });

  it('cannot use access token as refresh token', () => {
    const { accessToken } = oauthHandler.generateTokenPair(mockUser);
    const result = oauthHandler.refreshAccessToken(accessToken);
    expect(result).toBeNull();
  });
});
```

