constructor() {
  if (!process.env.JWT_SECRET) throw new Error('FATAL: JWT_SECRET 미설정');
  if (!process.env.JWT_REFRESH_SECRET) throw new Error('FATAL: JWT_REFRESH_SECRET 미설정');
